function toast(message,undo=false){const el=document.querySelector('#toast');el.innerHTML=`<span>${esc(message)}</span>${undo?'<button data-action="undo">撤销</button>':''}`;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),5000)}
function undo(){if(!undoSnapshot)return;data=undoSnapshot;undoSnapshot=null;save();render();toast('已撤销上一次操作')}
const btn=(text,action,ico='',style='',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;
const ib=(ico,label,action,extra='')=>`<button class="icon-button" aria-label="${label}" title="${label}" data-action="${action}" ${extra}>${icon(ico)}</button>`;
const opts=(entries,value)=>Object.entries(entries).map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${esc(l)}</option>`).join('');
function endTime(t){const [h,m]=t.time.split(':').map(Number);const minutes=h*60+m+Number(t.duration||60);return `${String(Math.floor(minutes/60)%24).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`}
function taskRow(t,{inbox=false,noTime=false}={}){return `<div class="task-row ${t.status==='done'?'done':''} ${t.status==='in_progress'?'in-progress':''} ${inbox?'inbox-row':''}" data-task="${esc(t.id)}">${!noTime?`<div class="task-time">${inbox?'未安排':t.time?`${esc(t.time)}<small>${endTime(t)}</small>`:'—'}</div>`:''}<button class="check ${inbox?selected.has(t.id)?'checked':'':t.status==='done'?'checked':''}" data-action="${inbox?'select-task':'complete'}" data-id="${esc(t.id)}" role="checkbox" aria-checked="${inbox?selected.has(t.id):t.status==='done'}" aria-label="${inbox?'选择':'标记完成'}：${esc(t.title)}">${(inbox?selected.has(t.id):t.status==='done')?icon('check'):''}</button><button class="task-main" data-action="detail" data-id="${esc(t.id)}"><div class="task-title">${esc(t.title)}</div><div class="task-meta">${t.project?`${icon('folder')}<span class="project-meta">${esc(t.project)}</span>`:inbox?'等待整理':''}${t.duration?`<span>${t.project?'· ':''}${t.duration} 分钟</span>`:''}${t.link?icon('link'):''}${t.priority==='high'?'<span style="color:#b48641">· 高优先级</span>':''}</div></button><div class="task-type">${icon(typeIcons[t.type])}${typeNames[t.type]}</div><div class="row-end">${t.status==='in_progress'?'<span class="pill blue">进行中</span>':t.status==='done'?icon('check'):''}</div><div class="row-actions">${ib('clock','延期任务','reschedule',`data-id="${esc(t.id)}"`)}${ib('more','查看任务详情','detail',`data-id="${esc(t.id)}"`)}</div></div>`}
function listHead(){return '<div class="list-head"><span class="time-head">时间</span><span class="task-head">任务</span><span class="type-head">类型</span><span style="width:50px"></span></div>'}
const empty=(title,message='从一个小任务开始，让想法有处安放。',showAdd=true)=>`<div class="empty">${icon('inbox')}<h3>${title}</h3><p>${message}</p>${showAdd?btn('添加任务','new','plus','primary'):''}</div>`;
function navItem(id,label,ico,count=''){return `<button class="nav-item ${page===id&&!filterType?'active':''}" data-action="navigate" data-page="${id}" title="${label}">${icon(ico)}<span>${label}</span>${count!==''?`<span class="count">${count}</span>`:''}</button>`}
function sidebar(){return `<aside class="sidebar"><div class="brand"><span class="brand-mark">${icon('atom')}</span><span>Research Tasks<span style="color:#2F80ED">.</span></span></div><button class="workspace" data-action="navigate" data-page="today"><span class="workspace-icon">${icon('folder')}</span><span class="grow"><span class="name">我的研究空间</span><span class="sub" style="display:block">Personal workspace</span></span>${icon('down')}</button><nav class="nav" aria-label="主要导航">${navItem('today','今天','sun')}${navItem('inbox','收集箱','inbox',data.tasks.filter(t=>t.status==='inbox').length)}${navItem('tasks','全部任务','tasks')}${navItem('calendar','日历','calendar')}${navItem('submissions','投稿追踪','submission')}</nav><div class="nav-label">任务分类</div><nav class="nav" aria-label="任务分类">${Object.entries(typeNames).slice(0,6).map(([k,v])=>`<button class="nav-item type-item ${filterType===k?'active':''}" data-action="category" data-type="${k}" title="${v}"><i class="type-dot"></i><span>${v}</span></button>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item ${page==='settings'?'active':''}" data-action="navigate" data-page="settings" title="设置">${icon('settings')}<span>设置与偏好</span></button><div class="profile"><span class="avatar">林</span><div class="profile-info grow"><div class="profile-name">林同学</div><div class="profile-role">个人研究空间</div></div>${ib('more','打开用户设置','navigate','data-page="settings"')}</div></div></aside>`}
function heading(title,subtitle,actions='',eyebrow=''){return `<header class="page-heading">${eyebrow?`<p class="eyebrow">${eyebrow}</p>`:''}<div class="between"><h1>${title}</h1><div class="heading-actions">${actions}</div></div><p class="page-subtitle">${subtitle}</p></header>`}
function command(){return `<form class="command" id="inline-command">${icon('spark','spark')}<input name="prompt" aria-label="AI 任务指令" placeholder="告诉我你接下来要完成什么……" autocomplete="off"><kbd>⌘ K</kbd><button aria-label="生成操作预览" type="submit">${icon('up')}</button></form><div class="command-hints"><span>让繁杂的计划，变得简单</span><span class="divider"></span><button data-action="plan">${icon('spark').replace('<svg','<svg style="width:11px;height:11px;vertical-align:-2px;margin-right:3px"')}帮我安排今天</button></div>`}
function todayPage(){let todayTasks=data.tasks.filter(t=>(t.date===TODAY||(!t.date&&t.due===TODAY))&&t.status!=='inbox'&&t.status!=='canceled');const scheduled=todayTasks.filter(t=>t.time).sort((a,b)=>a.time.localeCompare(b.time));const unscheduled=todayTasks.filter(t=>!t.time&&t.status!=='done');const overdue=data.tasks.filter(t=>t.due&&t.due<TODAY&&!['done','inbox','canceled'].includes(t.status));const completed=todayTasks.filter(t=>t.status==='done');return heading('今天',`10 月 30 日，星期五 <span style="color:#c2cad5">/</span> 把注意力，留给重要的研究。`,btn('添加任务','new','plus','primary'),'FRIDAY, OCTOBER 30')+command()+`${overdue.length?`<button class="overdue-button" data-action="overdue">${icon('clock')}有 ${overdue.length} 项任务已逾期${icon(showOverdue?'down':'chevron')}</button>${showOverdue?`<div class="overdue-list">${overdue.map(t=>taskRow(t)).join('')}</div>`:''}`:''}<div class="section-head"><h2>今日安排 <span class="small-count">${todayTasks.filter(t=>t.status!=='done').length}</span></h2><span class="section-caption">${completed.length} 项已完成 · 按时间排列</span></div>${listHead()}${scheduled.filter(t=>t.status!=='done').map((t,i)=>`${i===1&&scheduled.some(x=>x.status==='in_progress')?'<div class="current-line">当前工作时段</div>':''}${taskRow(t)}`).join('')||empty('今天还没有安排','可以先添加任务，或让 AI 生成待确认的安排。')}${btn('添加一项安排','new','plus','ghost subtle-add')}<div class="section-head"><h2>未安排 <span class="small-count">${unscheduled.length}</span></h2><span class="section-caption">有时间时，再往前一步</span></div>${unscheduled.map(t=>taskRow(t)).join('')||'<p class="small muted">今日任务均已安排时间。</p>'}${completed.length?`<button class="link-button" data-action="show-done" style="color:#8994a5;margin-top:17px">${icon(showDone?'down':'chevron')}已完成 ${completed.length} 项</button>${showDone?completed.map(t=>taskRow(t)).join(''):''}`:''}<div class="section-head" style="margin-top:30px"><h2>接下来</h2>${btn('查看日历','navigate','chevron','ghost','data-page="calendar"')}</div><button class="next-row" data-action="event"><span class="next-icon">${icon('calendar')}</span><span><span class="next-title">实验室每周组会</span><span class="next-meta" style="display:block">今天 16:00–17:00 · 会议室 302</span></span><span class="next-right">30 分钟前提醒</span>${icon('chevron')}</button><button class="next-row" data-action="submission" data-id="sub-1"><span class="next-icon">${icon('flag')}</span><span><span class="next-title">论文初稿内部讨论</span><span class="next-meta" style="display:block">11 月 2 日，星期一 · 投稿准备</span></span><span class="next-right">3 天后</span>${icon('chevron')}</button><footer class="page-footer">${icon('info')}演示场景 · 2026 年 10 月 30 日 · 数据仅保存在当前浏览器</footer>`}
function miniCalendar(){const d=new Date(`${miniDate}T12:00:00`),y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1);const start=new Date(y,m,1-((first.getDay()+6)%7));return `<div class="between"><span class="month-label">${y} 年 ${m+1} 月</span><div class="calendar-controls">${ib('left','上个月','mini-prev')}${ib('chevron','下个月','mini-next')}</div></div><div class="mini-calendar">${['一','二','三','四','五','六','日'].map(x=>`<div class="weekday">${x}</div>`).join('')}${Array.from({length:Math.ceil((((first.getDay()+6)%7)+new Date(y,m+1,0).getDate())/7)*7},(_,i)=>{const a=new Date(start);a.setDate(a.getDate()+i);const date=`${a.getFullYear()}-${String(a.getMonth()+1).padStart(2,'0')}-${String(a.getDate()).padStart(2,'0')}`;return `<button data-action="mini-day" data-date="${date}" aria-label="${fmt(date)}" class="${a.getMonth()!==m?'faded':''} ${date===TODAY?'today':''} ${date===calendarDate?'selected':''} ${data.tasks.some(t=>t.date===date&&t.time)?'has-event':''}">${a.getDate()}</button>`}).join('')}</div>`}
function hasConflict(){const t=data.tasks.find(t=>t.id==='task-4');if(!t||t.date!==TODAY||!t.time||['done','canceled'].includes(t.status))return false;const [h,m]=t.time.split(':').map(Number);return h*60+m<1020&&h*60+m+(t.duration||60)>960}
function context(){const next=data.submissions.filter(item=>item.due>=TODAY).sort((a,b)=>a.due.localeCompare(b.due))[0];return `<aside class="context" aria-label="日历和近期提醒">${miniCalendar()}<div class="calendar-legend"><i class="dot" style="width:4px;height:4px"></i>有日程安排</div><div class="context-divider"></div><div class="context-heading">近期提醒 ${ib('more','查看通知中心','notifications')}</div><div class="reminder"><span class="reminder-icon">${icon('calendar')}</span><div><div class="reminder-title">实验室每周组会 <span class="pill blue">今天</span></div><div class="reminder-time">16:00 · 提前 30 分钟提醒</div></div></div><div class="reminder"><span class="reminder-icon">${icon('flag')}</span><div><div class="reminder-title">论文初稿内部讨论</div><div class="reminder-time">11 月 2 日 · 09:30</div></div></div>${next?`<button class="reminder" data-action="submission" data-id="${esc(next.id)}" style="padding:0;text-align:left;width:100%"><span class="reminder-icon">${icon('submission')}</span><span><span class="reminder-title">${esc(next.name)} · ${esc(next.kind)}</span><span class="reminder-time" style="display:block">${fmt(next.due)} · ${esc(next.time)} ${esc(next.zone==='Etc/GMT+12'?'UTC−12':next.zone)}</span></span></button>`:''}<button class="link-button" data-action="notifications">查看所有提醒 ${icon('arrow')}</button>${!data.dismissInsight&&data.settings.proactive&&hasConflict()?`<section class="insight"><div class="insight-title">${icon('spark')}给计划留一点余地</div><p>今天 15:30 的实验与 16:00 的组会有时间重叠，可以将实验移至明天。</p><div class="between"><button class="link-button" data-action="conflict">查看调整建议 ${icon('arrow')}</button>${ib('close','忽略本次建议','dismiss-insight')}</div></section>`:''}<div class="context-bottom">所有安排由你决定。<br>AI 的每一次更改，都会先请你确认。</div></aside>`}
function inboxPage(){const items=data.tasks.filter(t=>t.status==='inbox').slice().reverse();return heading('收集箱','先捕捉想法，稍后再整理。',`<span class="pill">${items.length} 项待整理</span>`,'CAPTURE NOW, ORGANIZE LATER')+`<form id="quick-inbox" class="quick-add"><input class="field-input" name="title" required aria-label="快速记录任务" placeholder="想到什么，就先记在这里……" maxlength="200">${btn('记录','submit-inbox','plus','primary','type="submit"')}</form><div class="inbox-select"><span class="small muted">未安排的想法与待办</span><button class="link-button" data-action="select-all">${selected.size?'取消全选':'全选'}</button></div>${selected.size?`<div class="batch-bar"><span>已选择 ${selected.size} 项</span>${btn('AI 整理预览','organize','spark')}</div>`:''}${items.map(t=>taskRow(t,{inbox:true})).join('')||empty('收集箱已清空','随时记录新想法，不需要马上填写日期。',false)}<div class="notice">${icon('info').replace('<svg','<svg style="width:12px;height:12px;vertical-align:-2px;margin-right:5px"')}未提供日期的任务会保持未安排，整理时也不会自动添加截止日期。</div>`}
function filteredTasks(){return data.tasks.filter(t=>t.status!=='inbox'&&(!filterType||t.type===filterType)&&(!filterStatus||t.status===filterStatus)&&(!filterPriority||t.priority===filterPriority)&&(!filterDate||(filterDate==='today'?t.date===TODAY:filterDate==='overdue'?t.due&&t.due<TODAY&&!['done','canceled'].includes(t.status):!t.date))&&(!search||`${t.title} ${t.project} ${typeNames[t.type]}`.toLowerCase().includes(search.toLowerCase())))}
function taskResults(){const items=filteredTasks();if(!items.length)return empty('没有匹配的任务','试试调整筛选条件，或创建一项新任务。');return board?`<div class="board">${['todo','in_progress','done'].map(s=>`<section class="board-column"><h3>${statusNames[s]} <span class="muted">${items.filter(t=>t.status===s).length}</span></h3>${items.filter(t=>t.status===s).map(t=>`<button class="board-card" data-action="detail" data-id="${t.id}">${esc(t.title)}<small>${typeNames[t.type]} · ${t.date?fmt(t.date):'未安排'}</small></button>`).join('')}</section>`).join('')}</div>`:`${listHead()}${items.map(t=>taskRow(t)).join('')}`}
function tasksPage(){return heading(filterType?typeNames[filterType]:'全部任务','为每一项研究工作，找到合适的位置。',btn('添加任务','new','plus','primary'),'A LITTLE CLARITY, EVERY DAY')+`<div class="between"><span class="small muted">所有研究事项</span><div class="view-tabs"><button class="${!board?'active':''}" data-action="list-view" aria-label="列表视图">${icon('list')}</button><button class="${board?'active':''}" data-action="board-view" aria-label="看板视图">${icon('grid')}</button></div></div><div class="filters"><input class="field-input" id="task-search" value="${esc(search)}" placeholder="搜索任务、项目……" aria-label="搜索任务"><select id="filter-type" aria-label="按类型筛选">${opts({'':'全部类型',...typeNames},filterType)}</select><select id="filter-status" aria-label="按状态筛选">${opts({'':'全部状态',todo:'待开始',in_progress:'进行中',done:'已完成',canceled:'已取消'},filterStatus)}</select><select id="filter-priority" aria-label="按优先级筛选">${opts({'':'全部优先级',high:'高优先级',normal:'普通优先级',low:'低优先级'},filterPriority)}</select><select id="filter-date" aria-label="按日期筛选">${opts({'':'全部日期',today:'今天',overdue:'已逾期',unscheduled:'未安排'},filterDate)}</select></div><div id="task-results">${taskResults()}</div>`}
function weekDates(){let d=calendarDate;const day=new Date(`${d}T12:00:00`).getDay();d=addDays(d,-((day+6)%7));return Array.from({length:7},(_,i)=>addDays(d,i))}
function calendarPage(){const days=calendarView==='day'?[calendarDate]:weekDates();const dateLabel=calendarView==='month'?fmt(calendarDate,{year:'numeric',month:'long'}):calendarView==='day'?fmt(calendarDate):`${fmt(days[0])} — ${fmt(days[6])}`;let html=heading('日历','让研究有节奏，也给思考留白。','','MAKE ROOM FOR DEEP WORK')+`<div class="calendar-toolbar"><span class="range">${dateLabel}</span>${ib('left','上一个日期区间','cal-prev')}${ib('chevron','下一个日期区间','cal-next')}${btn('今天','cal-today')}<div class="view-tabs">${[['day','日'],['week','周'],['month','月']].map(([k,v])=>`<button class="${calendarView===k?'active':''}" data-action="cal-view" data-view="${k}">${v}</button>`).join('')}</div></div>`;
if(calendarView==='month'){const d=new Date(`${calendarDate}T12:00:00`);const first=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;const start=addDays(first,-((new Date(`${first}T12:00:00`).getDay()+6)%7));html+=`<div class="month-grid">${Array.from({length:42},(_,i)=>{const date=addDays(start,i),tasks=data.tasks.filter(t=>t.date===date&&t.status!=='inbox');return `<button class="month-cell ${date===TODAY?'today':''}" data-action="calendar-day" data-date="${date}"><span>${fmt(date,{day:'numeric'})}</span>${tasks.slice(0,2).map(t=>`<small>${esc(t.title)}</small>`).join('')}${tasks.length>2?`<small>还有 ${tasks.length-2} 项</small>`:''}</button>`}).join('')}</div>`}else{html+=`<div class="calendar-grid" style="--days:${days.length}"><div class="week-head"><div></div>${days.map(date=>`<div class="${date===TODAY?'today':''}">${fmt(date,{weekday:'short'})}<strong>${new Date(`${date}T12:00:00`).getDate()}</strong></div>`).join('')}</div><div class="week-body"><div class="time-axis">${Array.from({length:11},(_,i)=>`<span style="top:${i*60+8}px">${String(i+8).padStart(2,'0')}:00</span>`).join('')}</div>${days.map(date=>`<div class="day-column ${date===TODAY?'is-today':''}" data-date="${date}">${data.tasks.filter(t=>t.date===date&&t.time&&!['inbox','canceled'].includes(t.status)).map(t=>{const[h,m]=t.time.split(':').map(Number);return `<button class="calendar-event ${t.status==='done'?'green':''}" data-action="detail" data-id="${t.id}" style="top:${(h-8)*60+m}px;height:${Math.max(35,t.duration)}px">${esc(t.title)}<small>${t.time}–${endTime(t)}</small></button>`}).join('')}${date===TODAY?`<button class="calendar-event amber" data-action="event" style="top:480px;height:60px">实验室每周组会<small>16:00–17:00${hasConflict()?' · 与实验时间重叠':''}</small></button>`:''}</div>`).join('')}</div></div>`}return html+`<div class="calendar-note"><span><i class="dot" style="background:#719cce"></i>计划工作块</span><span><i class="dot" style="background:#cf9d4e"></i>会议 / 活动</span><span><i class="dot" style="background:#72ab92"></i>已完成</span></div><p class="small muted">点击空白时段添加安排；点击工作块查看详情。拖拽改期留待后续实现。</p>`}
const stages={Planning:'计划中',Preparing:'准备中','Internal Review':'内部审阅',Submitted:'已投稿','Under Review':'审稿中','Rebuttal/Revision':'答辩 / 修改',Decision:'等待决定',Accepted:'已录用',Rejected:'未录用',Withdrawn:'已撤回'};
function submissionsPage(){return heading('投稿追踪','重要的研究，值得从容准备。',btn('添加投稿','new-submission','plus','primary'),'FROM IDEAS TO SUBMISSIONS')+`<div class="notice" style="margin-top:0">会议日期参照 <a href="https://github.com/ccfddl/ccf-deadlines" target="_blank" rel="noopener noreferrer">CCF-Deadlines</a> 本地快照（2026-10-30），不自动更新；个人投稿阶段与准备事项为演示内容。</div><div class="submissions-list">${data.submissions.slice().sort((a,b)=>a.due.localeCompare(b.due)).map(s=>{const days=Math.ceil((new Date(s.due+'T12:00:00')-new Date(TODAY+'T12:00:00'))/86400000);return `<button class="submission-card" data-action="submission" data-id="${s.id}"><div class="flex" style="gap:15px"><span class="submission-mark">${esc(s.letter||s.name[0])}</span><div class="grow"><h2>${esc(s.name)}</h2><p class="submission-subtitle">${esc(s.subtitle||s.project)}</p></div><span class="pill ${s.stage==='Preparing'?'blue':''}">${stages[s.stage]}</span></div><div class="submission-stages">${Array.from({length:6},(_,i)=>`<span class="${i<Math.max(1,Object.keys(stages).indexOf(s.stage)+1)?'filled':''}"></span>`).join('')}</div><p class="small muted">下一步 · ${esc(s.action)}</p><div class="submission-detail-row"><div><label>下一关键日期</label><p>${esc(s.kind)} · ${esc(s.due)} ${esc(s.time)}</p><p class="muted" style="font-size:10px;margin-top:5px">${esc(s.zone==='Etc/GMT+12'?'UTC−12 / AoE':s.zone)}${s.source?' · CCF-DDL 快照':''}</p></div><div><label>距当前节点（基准日 10/30）</label><p style="color:${days<8?'#b48237':'#5c7698'}">${days>=0?`${days} 天`:'已截止'}</p></div><div><label>提醒</label><p>提前 ${esc(s.reminder)}</p></div></div></button>`}).join('')}</div>`}
function toggle(name,checked,label){return `<label class="toggle"><input type="checkbox" name="${name}" ${checked?'checked':''} aria-label="${label}"><span></span></label>`}
function settingsPage(){const s=data.settings;const tabs={general:'通用设置',notifications:'提醒通知',ai:'AI 偏好',integrations:'外部连接'};let body='';if(settingsTab==='general')body=`<section class="settings-section"><h2>时间与工作习惯</h2><p class="small muted">按自己的节奏安排研究。</p><div class="setting-row"><div><label for="timezone">默认时区</label><p>任务与日历时间将使用此时区显示</p></div><select id="timezone" name="timezone">${opts({'Asia/Shanghai':'Asia/Shanghai (UTC+8)','Asia/Tokyo':'Asia/Tokyo (UTC+9)','Europe/London':'Europe/London','America/Los_Angeles':'America/Los_Angeles'},s.timezone)}</select></div><div class="setting-row"><label for="workStart">工作开始时间</label><input type="time" id="workStart" name="workStart" value="${s.workStart}"></div><div class="setting-row"><label for="workEnd">工作结束时间</label><input type="time" id="workEnd" name="workEnd" value="${s.workEnd}"></div><div class="setting-row"><label for="workWeek">工作周</label><select id="workWeek" name="week">${opts({'周一至周五':'周一至周五','周一至周六':'周一至周六','每天':'每天'},s.week)}</select></div></section><section class="settings-section"><h2>快捷键</h2><div class="setting-row"><label>打开 AI 命令栏</label><kbd>⌘ / Ctrl + K</kbd></div><div class="setting-row"><label>关闭面板</label><kbd>Esc</kbd></div></section>`;
if(settingsTab==='notifications')body=`<section class="settings-section"><h2>少一些打扰，不错过重要安排</h2><div class="setting-row"><div><label>应用内提醒</label><p>在通知中心查看到期事项</p></div>${toggle('notify',s.notify,'应用内提醒')}</div><div class="setting-row"><div><label>夜间静音</label><p>22:00–08:00 不展示主动提醒</p></div>${toggle('quiet',s.quiet,'夜间静音')}</div><div class="notice">原型只演示应用内通知，不会申请系统推送权限或在后台派发真实提醒。</div></section>`;
if(settingsTab==='ai')body=`<section class="settings-section"><h2>让 AI 协助，保留你的决定权</h2><div class="setting-row"><div><label>AI 入口</label><p>开启自然语言指令与结构化预览</p></div>${toggle('ai',s.ai,'AI 入口')}</div><div class="setting-row"><div><label>基于上下文的建议</label><p>仅在时间冲突或截止风险时展示</p></div>${toggle('proactive',s.proactive,'主动建议')}</div><div class="setting-row"><label>写入确认策略</label><span class="pill blue">所有更改先预览、再确认</span></div><div class="notice">本原型通过本地规则模拟解析，不调用模型，也不发送任务数据。实际模型接入后仍需确认所有写入。</div></section>`;
if(settingsTab==='integrations')body=`<section class="settings-section"><h2>专业的事，交给专业的工具</h2><p class="small muted">任务中可保存外部资源链接，原型不读取外部内容。</p>${[['calendar','Google Calendar','日历与会议安排'],['book','Zotero','文献条目与论文链接'],['folder','GitHub','代码仓库与 Issues']].map(([i,n,d])=>`<div class="setting-row"><div class="flex" style="gap:13px">${icon(i)}<div><label>${n}</label><p>${d}</p></div></div><span class="pill">未连接 · 原型展示</span></div>`).join('')}</section>`;return heading('设置与偏好','让工具适应你，而不是反过来。','','YOUR SPACE, YOUR PACE')+`<div class="settings-tabs">${Object.entries(tabs).map(([k,v])=>`<button class="${settingsTab===k?'active':''}" data-action="settings-tab" data-tab="${k}">${v}</button>`).join('')}</div><form id="settings-form">${body}${settingsTab!=='integrations'?`<div class="between" style="margin-top:24px"><span class="small muted">仅影响当前浏览器中的演示偏好</span><button class="btn primary" type="submit">保存设置</button></div>`:''}</form>`}
function render(){const labels={today:'今天',inbox:'收集箱',tasks:'全部任务',calendar:'日历',submissions:'投稿追踪',settings:'设置与偏好'};document.title=`Research Tasks · ${labels[page]}`;document.querySelector('#app').innerHTML=`${sidebar()}<header class="topbar">${ib('menu','展开导航','mobile-menu')}<div class="breadcrumb"><span>个人空间</span>${icon('chevron')}<strong>${labels[page]}</strong></div><button class="topbar-search" data-action="search">${icon('search')}<span>搜索任务或询问 AI</span><kbd>⌘ K</kbd></button><div class="topbar-actions"><span class="prototype-chip">交互原型</span><button class="icon-button notification-button ${data.notifications.some(n=>!n.read)&&data.settings.notify?'unread':''}" data-action="notifications" aria-label="通知中心">${icon('bell')}</button><button class="avatar" data-action="navigate" data-page="settings" aria-label="个人设置" style="width:27px;height:27px;font-size:10px">林</button></div></header><div class="main-wrap ${page!=='today'?'full':''}"><main class="content" id="main-content">${({today:todayPage,inbox:inboxPage,tasks:tasksPage,calendar:calendarPage,submissions:submissionsPage,settings:settingsPage}[page])()}</main>${page==='today'?context():''}</div>`;document.querySelector('.topbar .icon-button')?.classList.add('mobile-menu')}
function navigate(next,{type='',keep=false}={}){page=next;filterType=type;if(!keep){search='';filterStatus='';filterPriority='';filterDate=''}selected.clear();closeOverlay(false);history.pushState(null,'',`#/${next}${type?'?type='+type:''}`);render();window.scrollTo(0,0)}
function overlay(html,{drawer=false,wide=false,title=''}={}){closeOverlay(false);lastFocus=document.activeElement;const root=document.querySelector('#overlay-root');root.innerHTML=`<div class="backdrop ${drawer?'detail-backdrop':''}"><section class="${drawer?'drawer':`dialog ${wide?'wide':''}`}" role="dialog" aria-modal="true" aria-label="${esc(title)}">${html}</section></div>`;document.body.style.overflow='hidden';requestAnimationFrame(()=>root.querySelector('input:not([type=hidden]),select,textarea,button')?.focus())}
function closeOverlay(restore=true){document.querySelector('#overlay-root').innerHTML='';document.body.style.overflow='';activeProposal=null;if(restore){lastFocus?.focus();const route=location.hash.match(/^#\/(?:tasks|submissions)\/([^?]+)/);if(route)history.replaceState(null,'',`#/${page}`)}}
const dialogHead=title=>`<div class="dialog-head"><h2>${title}</h2>${ib('close','关闭面板','close')}</div>`;
function taskForm(t={},isNew=false){return `<div class="form-group"><label for="task-title">任务名称</label><input id="task-title" class="field-input" name="title" required maxlength="200" placeholder="接下来要完成什么？" value="${esc(t.title||'')}"></div><div class="form-grid"><div class="form-group"><label for="task-type">任务类型</label><select name="type" id="task-type">${opts(typeNames,t.type||'research')}</select></div><div class="form-group"><label for="task-priority">优先级</label><select name="priority" id="task-priority">${opts({normal:'普通',high:'高',low:'低'},t.priority||'normal')}</select></div><div class="form-group"><label for="task-date">计划日期</label><input type="date" name="date" id="task-date" value="${t.date||''}"><p class="help">留空将保持未安排</p></div><div class="form-group"><label for="task-time">开始时间</label><input type="time" name="time" id="task-time" value="${t.time||''}"></div><div class="form-group"><label for="task-duration">预计耗时（分钟）</label><input type="number" name="duration" id="task-duration" min="0" max="1440" step="5" value="${t.duration||''}"></div><div class="form-group"><label for="task-due">完成截止日期</label><input type="date" name="due" id="task-due" value="${t.due||''}"><p class="help">截止日期与计划开始时间相互独立</p></div></div>${!isNew?`<div class="form-group"><label for="task-status">状态</label><select id="task-status" name="status">${opts(statusNames,t.status||'todo')}</select></div>`:''}<details ${!isNew?'open':''}><summary class="small muted" style="cursor:pointer;margin:8px 0">项目、外部链接与备注</summary><div class="form-group"><label for="task-project">关联项目</label><input class="field-input" name="project" id="task-project" value="${esc(t.project||'')}"></div><div class="form-group"><label for="task-link">外部资源链接</label><input class="field-input" type="url" id="task-link" name="link" placeholder="https://" value="${esc(t.link||'')}"></div><div class="form-group"><label for="task-note">备注</label><textarea id="task-note" name="note">${esc(t.note||'')}</textarea></div></details><div class="error-text" id="form-error" role="alert"></div>`}
function newTask(prefill={}){overlay(`${dialogHead('添加任务')}<form id="new-task"><div class="dialog-body">${taskForm(prefill,true)}<p class="small muted">只需要填写标题；未安排日期的任务会进入收集箱。</p></div><div class="dialog-footer">${btn('取消','close')}<button class="btn primary" type="submit">创建任务</button></div></form>`,{title:'添加任务'})}
function detail(id){const t=data.tasks.find(t=>t.id===id);if(!t)return;overlay(`<div class="drawer-head between"><span class="small muted">任务详情</span>${ib('close','关闭详情','close')}</div><form id="edit-task" data-id="${t.id}" style="display:contents"><div class="drawer-body"><div class="task-status"><span class="pill ${t.status==='in_progress'?'blue':''}">${statusNames[t.status]}</span></div><h2>${esc(t.title)}</h2>${taskForm(t)}</div><div class="drawer-footer">${btn('删除','delete','trash','danger',`data-id="${t.id}"`)}<div class="flex">${btn('延期','reschedule','clock','',`data-id="${t.id}"`)}<button class="btn primary" type="submit">保存更改</button></div></div></form>`,{drawer:true,title:'任务详情'});history.replaceState(null,'',`#/tasks/${id}`)}
function readTask(form){const f=new FormData(form);const values=Object.fromEntries(f);values.title=String(values.title).trim();if(!values.title){form.querySelector('#form-error').textContent='请输入任务名称。';return null}if(values.link&&!/^https?:\/\//i.test(values.link)){form.querySelector('#form-error').textContent='外部链接仅支持 http 或 https。';return null}if(values.time&&!values.date){form.querySelector('#form-error').textContent='填写开始时间时，请同时选择计划日期。';return null}values.duration=Number(values.duration)||0;return values}
function confirmDelete(id){const t=data.tasks.find(t=>t.id===id);overlay(`${dialogHead('删除这项任务？')}<div class="dialog-body"><p class="small muted">${esc(t.title)}</p><div class="notice">删除会移除当前任务，本次操作支持通过提示条撤销。</div></div><div class="dialog-footer">${btn('保留任务','close')}${btn('确认删除','delete-confirm','trash','danger',`data-id="${id}"`)}</div>`,{title:'确认删除任务'})}
function reschedule(id){const t=data.tasks.find(t=>t.id===id);overlay(`${dialogHead('调整任务安排')}<form id="reschedule-form" data-id="${id}"><div class="dialog-body"><h3>${esc(t.title)}</h3><p class="small muted" style="margin-top:10px">当前安排：${t.date?fmt(t.date):'未安排'} ${t.time||''}</p><div class="form-grid"><div class="form-group"><label for="move-date">新的计划日期</label><input id="move-date" name="date" type="date" required value="${addDays(TODAY,1)}"></div><div class="form-group"><label for="move-time">开始时间</label><input id="move-time" name="time" type="time" value="${t.time||'09:00'}"></div></div><div class="notice">仅修改工作安排，完成截止日期${t.due?'（'+fmt(t.due)+'）':''}保持不变。</div></div><div class="dialog-footer">${btn('取消','close')}<button class="btn primary" type="submit">确认调整</button></div></form>`,{title:'调整任务安排'})}
function aiModal(prompt=''){if(!data.settings.ai){toast('请先在 AI 偏好中启用 AI 入口');return}overlay(`${dialogHead('你想完成什么？')}<div class="dialog-body"><form id="ai-form" class="ai-modal-command">${icon('spark')}<input name="prompt" aria-label="自然语言指令" placeholder="创建任务、查看安排，或规划今天……" value="${esc(prompt)}" required><button type="submit" class="icon-button" aria-label="生成预览">${icon('arrow')}</button></form><div id="ai-results">${prompt?'':'<div class="spacer"></div>'+[['创建一项任务','周五前完成模型消融实验，预计 4 小时','plus'],['查看今天的安排','我今天有哪些任务？','search'],['安排今天的工作','帮我安排今天','calendar']].map(([label,p,i])=>`<button class="ai-example" data-action="ai-example" data-prompt="${p}">${icon(i)}<span>${label}</span>${icon('chevron').replace('<svg','<svg style="margin-left:auto"')}</button>`).join('')}</div><p class="ai-note">本地演示解析 · 不连接真实模型 · 所有写入需确认<br>演示基准日：2026-10-30，Asia/Shanghai；含糊的日期将由你在预览中指定。</p></div>`,{wide:true,title:'AI 命令栏'});if(prompt)interpret(prompt)}
function parsePrompt(prompt){const duration=prompt.match(/(?:预计|耗时|用时)?\s*(\d+(?:\.\d+)?)\s*(小时|分钟)/);let title=prompt.replace(/^(?:帮我|请|创建任务[：:]?|添加任务[：:]?)/,'').replace(/[,，]?\s*预计.*$/,'').trim();let due='',date='',time='',needsDate=false;if(prompt.includes('明天'))due=addDays(TODAY,1);else if(prompt.includes('今天'))due=TODAY;else if(prompt.includes('下周五'))due=addDays(TODAY,7);else if(prompt.includes('周五'))due=TODAY;else if(/周[一二三四六日天]|下周|后天|月底/.test(prompt))needsDate=true;const explicit=prompt.match(/(20\d\d-\d{2}-\d{2})/);if(explicit){const d=new Date(`${explicit[1]}T12:00:00`);if(!Number.isNaN(d.valueOf())&&addDays(explicit[1],0)===explicit[1])due=explicit[1];else needsDate=true}const type=/实验|模型|训练|baseline/i.test(prompt)?'experiment':/论文|阅读|文献/.test(prompt)?'paper_reading':/学习|复习/.test(prompt)?'learning':/组会|汇报/.test(prompt)?'meeting_prep':'research';return{title,type,status:due?'todo':'inbox',date,time,due,duration:duration?Math.round(Number(duration[1])*(duration[2]==='小时'?60:1)):0,priority:'normal',project:'',note:'',link:'',needsDate}}
function interpret(prompt){const container=document.querySelector('#ai-results');if(!container)return;if(!prompt.trim())return;container.innerHTML='<div class="preview-title"><span class="loading-dot"></span>正在生成演示预览……</div>';setTimeout(()=>{if(!document.querySelector('#ai-results'))return;if(/(?:推迟|延期|调整|删除)/.test(prompt)){const matches=data.tasks.filter(t=>!['done','canceled'].includes(t.status)&&prompt.includes(t.title));document.querySelector('#ai-results').innerHTML=`<div class="preview-title">${icon('info')}选择需要${prompt.includes('删除')?'删除':'调整'}的任务</div><p class="small muted">演示模式下，请选择明确的任务，再确认具体变更。</p>${(matches.length?matches:data.tasks.filter(t=>t.date===TODAY&&t.status!=='done')).map(t=>`<button class="next-row" data-action="${prompt.includes('删除')?'delete':'reschedule'}" data-id="${t.id}"><span class="grow">${esc(t.title)}</span>${icon('chevron')}</button>`).join('')}`;return}if(/(?:有哪些|查询|查看|总结|复盘)/.test(prompt)){const items=data.tasks.filter(t=>t.date===TODAY&&t.status!=='done');document.querySelector('#ai-results').innerHTML=`<div class="preview-title">${icon('search')}只读查询 · 今日安排</div><p class="small muted">今天还有 ${items.length} 项待办。以下结果来自当前浏览器的演示数据。</p>${items.map(t=>`<button class="next-row" data-action="detail" data-id="${t.id}"><span class="grow">${esc(t.title)}</span><span class="small muted">${t.time||'未安排'}</span></button>`).join('')}`;return}if(/安排|排程|计划/.test(prompt)&&!/创建|完成/.test(prompt)){showPlan(/下周/.test(prompt));return}const parsed=parsePrompt(prompt);activeProposal={kind:'create',task:parsed};document.querySelector('#ai-results').innerHTML=`<div class="preview-title">${icon('spark')}创建任务 · 待你确认</div><form id="ai-create-form"><div class="preview-summary"><div class="form-group" style="margin-top:0"><label for="ai-title">任务名称</label><input class="field-input" name="title" id="ai-title" maxlength="200" value="${esc(parsed.title)}" required></div><div class="form-grid"><div class="form-group"><label for="ai-type">类型</label><select id="ai-type" name="type">${opts(typeNames,parsed.type)}</select></div><div class="form-group"><label for="ai-due">截止日期${parsed.needsDate?' · 请指定具体日期':''}</label><input type="date" id="ai-due" name="due" value="${parsed.due}" ${parsed.needsDate?'required':''}></div><div class="form-group"><label for="ai-duration">预计耗时（分钟）</label><input id="ai-duration" type="number" name="duration" min="0" max="1440" value="${parsed.duration||''}"></div><div class="form-group"><label for="ai-priority">优先级</label><select id="ai-priority" name="priority">${opts({normal:'普通',high:'高',low:'低'},'normal')}</select></div></div><p class="small muted">计划开始：未安排 · 提醒：未设置</p></div><div class="notice">${parsed.needsDate?'未能明确识别日期，请选择具体截止日期。':parsed.due?'识别为纯日期截止，不会自动生成工作块。':'未识别到日期，将创建到收集箱，不添加截止日期。'}</div><div class="flex" style="justify-content:flex-end;margin-top:18px">${btn('取消','close')}<button class="btn primary" type="submit">确认创建</button></div></form>`},380)}
function showPlan(nextWeek=false,conflict=false){const items=conflict?data.tasks.filter(t=>t.id==='task-4'):data.tasks.filter(t=>!t.time&&t.status==='todo'&&(!t.date||t.date===TODAY));const target=conflict?addDays(TODAY,1):nextWeek?addDays(TODAY,3):TODAY;activeProposal={kind:'plan',ids:items.map(t=>t.id),date:target};const container=document.querySelector('#ai-results');if(!container)return;container.innerHTML=`<div class="preview-title">${icon('calendar')}${conflict?'解决时间冲突':'安排工作块'} · ${items.length} 项变更</div>${!items.length?'<p class="small muted">目前没有需要安排的任务。</p>':`<form id="plan-form"><div class="notice" style="margin-top:0">${conflict?'15:30–17:00 的实验与 16:00–17:00 的组会重叠。建议只移动实验，保留已确认会议。':'这是供你编辑的演示建议。保留现有会议与工作块，不修改任务截止日期。'}</div>${items.map((t,i)=>`<div class="preview-change"><div class="grow">${esc(t.title)}<small>原安排：${t.date?fmt(t.date):'未安排日期'} ${t.time||'未安排时间'}</small><div class="form-grid" style="margin-top:10px"><input aria-label="${esc(t.title)}的新日期" type="date" name="date-${t.id}" value="${target}" required><input aria-label="${esc(t.title)}的新时间" type="time" name="time-${t.id}" value="${conflict?'09:00':i===0?'13:00':'17:15'}" required></div></div></div>`).join('')}<div id="plan-error" class="error-text" role="alert"></div><div class="flex" style="justify-content:flex-end;margin-top:18px">${btn('取消','close')}<button class="btn primary" type="submit">确认 ${items.length} 项调整</button></div></form>`}`}
function plan(conflict=false){aiModal();if(document.querySelector('#ai-results'))showPlan(false,conflict)}
function organize(){const items=data.tasks.filter(t=>selected.has(t.id));if(!items.length)return;overlay(`${dialogHead('整理收集箱')}<div class="dialog-body"><p class="small muted">将 ${items.length} 项移入全部任务，保留未安排状态。</p>${items.map(t=>`<div class="preview-change"><span>${esc(t.title)}</span><span class="pill">${typeNames[t.type]}</span></div>`).join('')}<div class="notice">不推断截止日期，不创建工作块。</div></div><div class="dialog-footer">${btn('取消','close')}${btn('确认整理','organize-confirm','check','primary')}</div>`,{title:'整理预览'})}
function notifications(){overlay(`<div class="drawer-head between"><h2>通知中心</h2>${ib('close','关闭通知中心','close')}</div><div class="drawer-body"><div class="between"><span class="small muted">${data.notifications.filter(n=>!n.read).length} 条未读</span><button class="link-button" data-action="read-all">全部标为已读</button></div>${data.notifications.map(n=>`<section class="notification-item ${n.read?'read':''}"><div class="between"><h3>${esc(n.title)}</h3>${!n.read?'<i class="dot"></i>':''}</div><p class="muted">${esc(n.body)}</p><div class="actions"><button data-action="notification-open" data-id="${n.id}">查看事项</button><button data-action="notification-read" data-id="${n.id}">${n.read?'已读':'标为已读'}</button><button data-action="notification-snooze" data-id="${n.id}">稍后提醒</button></div>${n.snooze?`<p class="small muted">本次已设为稍后处理 · 仅演示</p>`:''}</section>`).join('')}<div class="notice">原型不会在浏览器关闭后发送提醒。</div></div>`,{drawer:true,title:'通知中心'})}
function eventDetail(){overlay(`${dialogHead('实验室每周组会')}<div class="dialog-body"><span class="pill amber">会议 · 演示事件</span><dl class="preview-fields"><dt>日期</dt><dd>2026 年 10 月 30 日，星期五</dd><dt>时间</dt><dd>16:00–17:00 · Asia/Shanghai</dd><dt>地点</dt><dd>会议室 302</dd><dt>提醒</dt><dd>提前 30 分钟</dd></dl>${hasConflict()?'<div class="notice">与“复现对比学习 baseline”的计划工作块重叠 60 分钟。</div>':''}<div class="section-head"><h2>关联准备任务</h2></div>${data.tasks.filter(t=>t.type==='meeting_prep'&&t.status!=='inbox').map(t=>`<button class="next-row" data-action="detail" data-id="${t.id}">${icon('tasks')}<span>${esc(t.title)}</span>${icon('chevron')}</button>`).join('')}</div><div class="dialog-footer">${btn('关闭','close')}${btn('查看调整建议','conflict','spark','primary')}</div>`,{title:'会议详情'})}
function submissionForm(s={}){return `<div class="form-group"><label for="sub-name">会议 / 期刊名称</label><input class="field-input" id="sub-name" name="name" value="${esc(s.name||'')}" required></div><div class="form-group"><label for="sub-project">关联研究</label><input class="field-input" id="sub-project" name="project" value="${esc(s.project||'')}"></div><div class="form-group"><label for="sub-stage">投稿阶段</label><select id="sub-stage" name="stage">${opts(stages,s.stage||'Planning')}</select></div><div class="form-group"><label for="sub-kind">关键日期类型</label><select id="sub-kind" name="kind">${opts({'Abstract Deadline':'Abstract Deadline','Full Paper Deadline':'Full Paper Deadline','Supplementary Deadline':'Supplementary Deadline',Rebuttal:'Rebuttal',Notification:'Notification','Camera-ready':'Camera-ready'},s.kind||'Full Paper Deadline')}</select></div><div class="form-grid"><div class="form-group"><label for="sub-due">截止日期</label><input type="date" name="due" id="sub-due" value="${s.due||''}" required></div><div class="form-group"><label for="sub-time">截止时间</label><input type="time" step="1" name="time" id="sub-time" value="${s.time||'23:59'}" required></div></div><div class="form-group"><label for="sub-zone">官方时区（须明确选择）</label><select name="zone" id="sub-zone" required>${opts({'':'请选择官方时区','Etc/GMT+12':'UTC−12 · AoE','America/Los_Angeles':'America/Los_Angeles','Asia/Shanghai':'Asia/Shanghai','Europe/London':'Europe/London'},s.zone||'')}</select></div><div class="form-group"><label for="sub-action">下一项关键动作</label><input class="field-input" name="action" id="sub-action" value="${esc(s.action||'')}"></div><div class="form-group"><label for="sub-reminder">提前提醒</label><select name="reminder" id="sub-reminder">${opts({'30、14、7、3、1 天':'30、14、7、3、1 天','14、7、3、1 天':'14、7、3、1 天','7、3、1 天':'7、3、1 天','1 天':'1 天'},s.reminder||'30、14、7、3、1 天')}</select></div>`}
function submissionSources(s){if(!s.source)return '';return `<section class="settings-section"><h2>CCF-DDL 收录节点</h2><p class="small muted" style="margin-top:8px">${esc(s.checkedAt)} 本地快照 · ${esc(s.sourceZone)} · 不自动更新</p>${(s.milestones||[]).map(m=>`<div class="preview-change"><span>${esc(m.kind)}</span><span class="small muted">${esc(m.date)}<br>${esc(m.time)} UTC−12</span></div>`).join('')}<div class="flex" style="margin-top:15px;gap:18px"><a href="${esc(s.source)}" target="_blank" rel="noopener noreferrer" class="small">查看数据源 ↗</a><a href="${esc(s.official)}" target="_blank" rel="noopener noreferrer" class="small">会议官网 ↗</a></div></section>`}
function submission(id){const s=data.submissions.find(s=>s.id===id);if(!s)return;overlay(`<div class="drawer-head between"><span class="small muted">投稿详情 · 本地记录</span>${ib('close','关闭投稿详情','close')}</div><form id="edit-submission" data-id="${id}" style="display:contents"><div class="drawer-body"><h2>${esc(s.name)}</h2>${submissionForm(s)}${submissionSources(s)}<div class="notice">手动编辑仅修改当前节点；来源快照保留供核对，不会自动覆盖你的更改。</div></div><div class="drawer-footer">${btn('取消','close')}<button type="submit" class="btn primary">确认保存</button></div></form>`,{drawer:true,title:'投稿详情'});history.replaceState(null,'',`#/submissions/${id}`)}
function newSubmission(){overlay(`${dialogHead('添加投稿')}<form id="new-submission"><div class="dialog-body">${submissionForm()}</div><div class="dialog-footer">${btn('取消','close')}<button type="submit" class="btn primary">添加投稿</button></div></form>`,{title:'添加投稿'})}
document.addEventListener('click',e=>{if(e.target.classList.contains('backdrop')){closeOverlay();return}const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;switch(a){case 'navigate':navigate(el.dataset.page);break;case 'category':navigate('tasks',{type:el.dataset.type});break;case 'new':newTask();break;case 'close':closeOverlay();break;case 'detail':detail(id);break;case 'complete':{snapshot();const t=data.tasks.find(t=>t.id===id);t.status=t.status==='done'?'todo':'done';save();render();toast(t.status==='done'?'任务已完成':'任务已恢复',true);break}case 'reschedule':reschedule(id);break;case 'delete':confirmDelete(id);break;case 'delete-confirm':snapshot();data.tasks=data.tasks.filter(t=>t.id!==id);save();closeOverlay();render();toast('任务已删除',true);break;case 'undo':undo();break;case 'show-done':showDone=!showDone;render();break;case 'overdue':showOverdue=!showOverdue;render();break;case 'search':aiModal();break;case 'ai-example':aiModal(el.dataset.prompt);break;case 'plan':plan();break;case 'conflict':plan(true);break;case 'dismiss-insight':data.dismissInsight=true;save();render();break;case 'notifications':notifications();break;case 'read-all':data.notifications.forEach(n=>n.read=true);save();render();notifications();break;case 'notification-read':data.notifications.find(n=>n.id===id).read=true;save();render();notifications();break;case 'notification-snooze':{const n=data.notifications.find(n=>n.id===id);n.snooze=true;n.read=true;save();render();notifications();toast('已设为稍后处理（原型演示）');break}case 'notification-open':{const n=data.notifications.find(n=>n.id===id);n.read=true;save();navigate(n.target);break}case 'select-task':selected.has(id)?selected.delete(id):selected.add(id);render();break;case 'select-all':if(selected.size)selected.clear();else data.tasks.filter(t=>t.status==='inbox').forEach(t=>selected.add(t.id));render();break;case 'organize':organize();break;case 'organize-confirm':snapshot();data.tasks.filter(t=>selected.has(t.id)).forEach(t=>t.status='todo');selected.clear();save();closeOverlay();render();toast('已整理到全部任务，日期保持未安排',true);break;case 'list-view':board=false;render();break;case 'board-view':board=true;render();break;case 'mini-prev':case 'mini-next':{const d=new Date(`${miniDate}T12:00:00`);d.setDate(1);d.setMonth(d.getMonth()+(a==='mini-prev'?-1:1));miniDate=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;render();break}case 'mini-day':calendarDate=el.dataset.date;navigate('calendar');break;case 'cal-prev':case 'cal-next':{const n=a==='cal-prev'?-1:1;if(calendarView==='month'){const d=new Date(`${calendarDate}T12:00:00`);d.setDate(1);d.setMonth(d.getMonth()+n);calendarDate=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`}else calendarDate=addDays(calendarDate,n*(calendarView==='day'?1:7));render();break}case 'cal-today':calendarDate=TODAY;render();break;case 'cal-view':calendarView=el.dataset.view;render();break;case 'calendar-day':calendarDate=el.dataset.date;calendarView='day';render();break;case 'event':eventDetail();break;case 'submission':submission(id);break;case 'new-submission':newSubmission();break;case 'settings-tab':settingsTab=el.dataset.tab;render();break;case 'mobile-menu':document.querySelector('.sidebar').classList.toggle('open');break}});
document.addEventListener('click',e=>{const col=e.target.closest('.day-column');if(!col||e.target.closest('button'))return;const rect=col.getBoundingClientRect(),hour=Math.min(18,Math.max(8,Math.floor((e.clientY-rect.top)/60)+8));newTask({date:col.dataset.date,time:`${String(hour).padStart(2,'0')}:00`,duration:60})});
document.addEventListener('input',e=>{if(e.target.closest?.('#ai-form')&&document.querySelector('#ai-results')){const q=e.target.value.trim().toLowerCase();const matches=q?data.tasks.filter(t=>`${t.title} ${t.project}`.toLowerCase().includes(q)):[];if(matches.length){document.querySelector('#ai-results').innerHTML=`<div class="preview-title">${icon('search')}匹配的任务</div>${matches.map(t=>`<button class="next-row" data-action="detail" data-id="${t.id}"><span class="grow">${esc(t.title)}</span><span class="small muted">${statusNames[t.status]}</span></button>`).join('')}`}}if(e.target.id==='task-search'){search=e.target.value;document.querySelector('#task-results').innerHTML=taskResults()}});
document.addEventListener('change',e=>{const t=e.target;if(t.id.startsWith('filter-')){if(t.id==='filter-type')filterType=t.value;if(t.id==='filter-status')filterStatus=t.value;if(t.id==='filter-priority')filterPriority=t.value;if(t.id==='filter-date')filterDate=t.value;document.querySelector('#task-results').innerHTML=taskResults()}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);switch(form.id){case 'inline-command':case 'ai-form':{const prompt=String(f.get('prompt')||'').trim();if(prompt){if(form.id==='inline-command')aiModal(prompt);else interpret(prompt)}break}case 'quick-inbox':{const title=String(f.get('title')||'').trim();if(!title)return;snapshot();data.tasks.push({id:crypto.randomUUID(),title,type:'other',status:'inbox',date:'',time:'',duration:0,due:'',priority:'normal',project:'',note:'',link:''});save();render();toast('已记录到收集箱',true);break}case 'new-task':case 'edit-task':{const values=readTask(form);if(!values)return;snapshot();if(form.id==='new-task'){data.tasks.push({...values,id:crypto.randomUUID(),status:values.date||values.due?'todo':'inbox'})}else Object.assign(data.tasks.find(t=>t.id===form.dataset.id),values);save();closeOverlay();render();toast(form.id==='new-task'?'任务已保存到本地演示':'任务更改已保存',true);break}case 'reschedule-form':{snapshot();const t=data.tasks.find(t=>t.id===form.dataset.id);t.date=f.get('date');t.time=f.get('time');if(t.status==='inbox')t.status='todo';save();closeOverlay();render();toast('计划时间已调整，截止日期未更改',true);break}case 'ai-create-form':{if(!activeProposal)return;const title=String(f.get('title')||'').trim();if(!title)return;const parsed={...activeProposal.task,title,type:f.get('type'),due:f.get('due'),duration:Number(f.get('duration')||0),priority:f.get('priority')};delete parsed.needsDate;parsed.status=parsed.due?'todo':'inbox';snapshot();data.tasks.push({...parsed,id:crypto.randomUUID()});save();closeOverlay();render();toast('已确认，并保存到本地演示',true);break}case 'plan-form':{if(!activeProposal)return;const changes=activeProposal.ids.map(id=>({id,date:f.get(`date-${id}`),time:f.get(`time-${id}`)}));const work=data.tasks.map(t=>({...t,...(changes.find(c=>c.id===t.id)||{})}));let conflict='';for(const c of changes){const task=work.find(t=>t.id===c.id);const start=Number(c.time.slice(0,2))*60+Number(c.time.slice(3));const end=start+(task.duration||60);if(end>24*60){conflict='工作块跨越午夜，请调整时间。';break}if(c.date===TODAY&&start<17*60&&end>16*60){conflict='建议时间与 16:00–17:00 的组会重叠，请修改。';break}for(const other of work){if(other.id===c.id||other.date!==c.date||!other.time||['canceled','done','inbox'].includes(other.status))continue;const os=Number(other.time.slice(0,2))*60+Number(other.time.slice(3));if(start<os+(other.duration||60)&&end>os){conflict=`“${task.title}”与“${other.title}”时间重叠，请修改。`;break}}if(conflict)break}if(conflict){document.querySelector('#plan-error').textContent=conflict;return}snapshot();changes.forEach(c=>Object.assign(data.tasks.find(t=>t.id===c.id),c));save();closeOverlay();render();toast(`已确认 ${changes.length} 项安排`,true);break}case 'settings-form':{const v=Object.fromEntries(f);if(settingsTab==='general'&&v.workStart>=v.workEnd){toast('工作结束时间应晚于开始时间');return}Object.assign(data.settings,v);if(settingsTab==='notifications'){data.settings.notify=f.has('notify');data.settings.quiet=f.has('quiet')}if(settingsTab==='ai'){data.settings.ai=f.has('ai');data.settings.proactive=f.has('proactive')}save();render();toast('偏好已保存到当前浏览器');break}case 'new-submission':case 'edit-submission':{const v=Object.fromEntries(f);v.name=v.name.trim();if(!v.name)return;snapshot();if(form.id==='new-submission')data.submissions.push({...v,id:crypto.randomUUID(),letter:v.name[0],subtitle:''});else Object.assign(data.submissions.find(s=>s.id===form.dataset.id),v);save();closeOverlay();render();toast('投稿信息已保存到本地演示',true);break}}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();aiModal();return}if(e.key==='Escape'){closeOverlay();document.querySelector('.sidebar')?.classList.remove('open');return}if(e.key==='Tab'){const dialog=document.querySelector('[role=dialog]');if(!dialog)return;const focusable=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),select,textarea,summary,a[href]')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
function route(){const hash=location.hash.replace(/^#\//,'').split('?')[0],parts=hash.split('/');if(['today','inbox','tasks','calendar','submissions','settings'].includes(parts[0]))page=parts[0];else page='today';const query=new URLSearchParams(location.hash.split('?')[1]||'');filterType=query.get('type')||'';render();if(parts[1]){if(parts[0]==='tasks')detail(parts[1]);if(parts[0]==='submissions')submission(parts[1])}}
window.addEventListener('popstate',()=>{closeOverlay(false);route()});route();
